using JewelDesign.Documents;
using JewelDesign.Features.Candidate;
using JewelDesign.Geometry.Candidate;
namespace CandidateGeometryContractChecks;
internal static class MeshSnapshotAssertions
{
 static void Check(bool v,string m){if(!v)throw new Exception(m);}
 static CandidateVector3 Cross(CandidateVector3 a,CandidateVector3 b)=>new(a.Y*b.Z-a.Z*b.Y,a.Z*b.X-a.X*b.Z,a.X*b.Y-a.Y*b.X);
 static CandidateVector3 Sub(CandidatePoint3 a,CandidatePoint3 b)=>new(a.X-b.X,a.Y-b.Y,a.Z-b.Z);
 static double Dot(CandidateVector3 a,CandidateVector3 b)=>a.X*b.X+a.Y*b.Y+a.Z*b.Z;
 static double Volume(CandidateMeshSnapshot mesh){double value=0;foreach(var t in mesh.Triangles){var a=mesh.Vertices[(int)t.A].Position;var b=mesh.Vertices[(int)t.B].Position;var c=mesh.Vertices[(int)t.C].Position;value+=a.X*(b.Y*c.Z-b.Z*c.Y)+a.Y*(b.Z*c.X-b.X*c.Z)+a.Z*(b.X*c.Y-b.Y*c.X);}return value/6;}
 static void Validate(CandidateMeshSnapshot mesh){Check(mesh.Vertices.Count>0&&mesh.Triangles.Count>0,"Mesh snapshot empty");foreach(var v in mesh.Vertices)Check(double.IsFinite(v.Position.X)&&double.IsFinite(v.Position.Y)&&double.IsFinite(v.Position.Z)&&Math.Abs(Dot(v.Normal,v.Normal)-1)<1e-10,"Mesh vertex/normal invalid");foreach(var t in mesh.Triangles){Check(t.A<mesh.Vertices.Count&&t.B<mesh.Vertices.Count&&t.C<mesh.Vertices.Count&&t.Face<mesh.FaceCount,"Mesh indices/face invalid");var a=mesh.Vertices[(int)t.A];var b=mesh.Vertices[(int)t.B];var c=mesh.Vertices[(int)t.C];var n=Cross(Sub(b.Position,a.Position),Sub(c.Position,a.Position));if(Dot(n,n)>1e-24)Check(Dot(n,new(a.Normal.X+b.Normal.X+c.Normal.X,a.Normal.Y+b.Normal.Y+c.Normal.Y,a.Normal.Z+b.Normal.Z+c.Normal.Z))>0,"Mesh winding and normals disagree");}}
 static void Throws<T>(Action a)where T:Exception{try{a();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name);}
 public static string Run(){using var context=CandidateContext.Create();int cases=0,coarseTriangles=0,fineTriangles=0;CandidateMeshSnapshot detached;
  using(var box=context.CreateBox(2,3,4)){var before=context.GetShapeBounds(box,CandidateShapeBoundsMode.Fast);var mesh=context.TessellateBrep(box,.05,.35);Validate(mesh);Throws<NotSupportedException>(()=>((IList<CandidateMeshVertex>)mesh.Vertices)[0]=default);Throws<NotSupportedException>(()=>((IList<CandidateMeshTriangle>)mesh.Triangles)[0]=default);Check(mesh.FaceCount==6&&mesh.Triangles.Select(t=>t.Face).Distinct().Count()==6,"Box mesh lost a face");Check(Math.Abs(Volume(mesh)-24)<1e-7,"Mesh winding/volume differs from independent box");Check(context.GetShapeBounds(box,CandidateShapeBoundsMode.Fast)==before,"Meshing mutated original BRep/tolerances");detached=mesh;cases++;using var mirror=context.TransformAffine(box,new(-1,0,0,1,0,1,0,-2,0,0,1,.5));var reflected=context.TessellateBrep(mirror,.05,.35);Validate(reflected);Check(Math.Abs(Volume(reflected)-24)<1e-7,"Mirrored mesh winding lost outward volume");cases++;}
  using(var producer=CandidateContext.Create())using(var box=producer.CreateBox(1,2,3))detached=producer.TessellateBrep(box,.05,.35);Validate(detached);Check(Math.Abs(Volume(detached)-6)<1e-7,"Mesh snapshot lost data after producer disposal");cases++;
  using(var cylinder=context.CreateNurbsSurface(new(1,2,2,3,new[]{new CandidatePoint3(0,0,2),new(0,2,2),new(0,2,0),new(10,0,2),new(10,2,2),new(10,2,0)},new[]{0.0,0,1,1},new[]{0.0,0,0,1,1,1},new[]{1.0,Math.Sqrt(.5),1,1,Math.Sqrt(.5),1}),1e-8)){var mesh=context.TessellateBrep(cylinder,.01,.2);Validate(mesh);foreach(var v in mesh.Vertices){Check(Math.Abs(v.Position.Y*v.Position.Y+v.Position.Z*v.Position.Z-4)<1e-8,"Rational cylinder mesh left actual surface");Check(v.Normal.Y*v.Position.Y/2+v.Normal.Z*v.Position.Z/2>1-1e-6,"Curved normals do not follow analytic cylinder");}cases++;}
  using(var box=context.CreateBox(1,1,1))using(var far=context.Translate(box,10,0,0))using(var empty=context.Boolean(CandidateBooleanOperation.Common,box,far,0)){var mesh=context.TessellateBrep(empty,.05,.35);Check(mesh.Vertices.Count==0&&mesh.Triangles.Count==0&&mesh.FaceCount==0,"Empty BRep should produce genuinely empty mesh data");cases++;}
  using(var stream=typeof(MeshSnapshotAssertions).Assembly.GetManifestResourceStream("RingRailLibraryFixture")!)using(var memory=new MemoryStream()){
   stream.CopyTo(memory);var document=LegacyCsg4Codec.Read(memory.ToArray());using var graph=new CandidateRailGraphSession(context,document,new(1e-7,1e-7,1e-7));graph.Generate(140);using var shape=graph.RetainBrep(140);var before=context.GetShapeBounds(shape,CandidateShapeBoundsMode.Accurate);var coarse=context.TessellateBrep(shape,.08,.6);var fine=context.TessellateBrep(shape,.004,.15);Validate(coarse);Validate(fine);coarseTriangles=coarse.Triangles.Count;fineTriangles=fine.Triangles.Count;Check(coarse.FaceCount==3&&fine.FaceCount==3&&fine.Triangles.Count>coarse.Triangles.Count,"Actual regenerated mesh did not reflect finer settings/all faces");Check(context.GetShapeBounds(shape,CandidateShapeBoundsMode.Accurate)==before,"Mesh generation mutated joined input");cases+=2;
   graph.Values.SetValue(2,document.Records[2].Scalar!.Value+.25);graph.Generate(140);using var edited=graph.RetainBrep(140);var changed=context.TessellateBrep(edited,.004,.15);Validate(changed);Check(changed.Vertices.Max(v=>v.Position.Z)!=fine.Vertices.Max(v=>v.Position.Z),"Edited CAD did not regenerate mesh");cases++;
   using var loaded=new CandidateRailGraphSession(context,LegacyCsg4Codec.Read(LegacyCsg4Codec.Write(graph.Values.ExportCurrentDocument())),new(1e-7,1e-7,1e-7));loaded.Generate(140);using var reopened=loaded.RetainBrep(140);var saved=context.TessellateBrep(reopened,.004,.15);Validate(saved);Check(Math.Abs(Volume(saved)-Volume(changed))<1e-7,"Reopened mesh volume differs");cases++;
  }
  using(var box=context.CreateBox(1,1,1)){Throws<CandidateGeometryException>(()=>context.TessellateBrep(box,0,.3));Throws<CandidateGeometryException>(()=>context.TessellateBrep(box,.1,double.NaN));Throws<CandidateGeometryException>(()=>context.TessellateBrep(box,1e-9,.3));Throws<CandidateGeometryException>(()=>context.TessellateBrep(box,.1,4));using(var line=context.CreateLine(new(0,0,0),new(1,0,0)))Throws<CandidateGeometryException>(()=>context.TessellateBrep(line,.1,.3));using(var disposed=context.Clone(box)){disposed.Dispose();Throws<ObjectDisposedException>(()=>context.TessellateBrep(disposed,.1,.3));}using(var other=CandidateContext.Create())Throws<ArgumentException>(()=>other.TessellateBrep(box,.1,.3));}
  Check(context.DiagnosticLiveShapeCount==0,"Mesh snapshot retained native entries");return "PASS native BRep mesh snapshots:"+cases+" analytic/actual cases, normals/winding/indices/face ordinals, real coarse-fine/edit-save-reopen tessellation, copied inputs/detached lifetime/guards; actual-triangles="+coarseTriangles+"->"+fineTriangles+"; viewport/original-render/PC parity separate.";
 }
}
